import { ImageResponse } from "next/og";

// Sitewide sharing graphic: approved GOOOL Athletics logo, untouched.
// Its embedded bytes come from public/brand/goool-athletics-lockup-white.png.
// Keeping the asset inline avoids remote network requests when link crawlers load it.
export const runtime = "nodejs";
export const alt = "GOOOL Athletics. Wear the Feeling.";
export const size = { width: 1200, height: 630 };
export const contentType = "image/png";

const approvedLogo = "data:image/png;base64,";

export default function OpenGraphImage() {
  return new ImageResponse(
    <div
      style={{
        width: "100%",
        height: "100%",
        display: "flex",
        flexDirection: "column",
        alignItems: "center",
        justifyContent: "center",
        backgroundColor: "#0B0B0B",
      }}
    >
      <img
        src={approvedLogo}
        alt="GOOOL Athletics"
        width={930}
        height={349}
        style={{ objectFit: "contain" }}
      />
      <div
        style={{
          display: "flex",
          marginTop: 16,
          fontSize: 29,
          fontFamily: "Arial, sans-serif",
          fontWeight: 600,
          letterSpacing: 6,
          color: "#FFFFFF",
        }}
      >
        WEAR THE FEELING.
      </div>
    </div>,
    { ...size },
  );
}
